use std::collections::HashSet;

fn has_common_element(a: Vec<i32>, b: Vec<i32>) -> bool {
    // If either vector is empty, they cannot share any elements.
    if a.is_empty() || b.is_empty() {
        return false;
    }

    // Insert elements of the smaller vector into a HashSet for faster lookups
    // to optimize performance if one vector is much smaller than the other.
    if a.len() <= b.len() {
        let set_a: HashSet<i32> = a.into_iter().collect();

        // Check if any element of b exists in set_a
        b.into_iter().any(|x| set_a.contains(&x))
    } else {
        let set_b: HashSet<i32> = b.into_iter().collect();

        // Check if any element of a exists in set_b
        a.into_iter().any(|x| set_b.contains(&x))
    }
}